import datetime
from cryptography.hazmat.primitives.asymmetric import ed25519

def _today_bytes() -> bytes:
    """Return today's date as b'YYYY-MM-DD' (mockable in tests)."""
    return datetime.date.today().isoformat().encode()

def sign_with_timestamp(data: bytes, key: bytes) -> bytes:
    """Sign `data` + today's date with an Ed25519 private key."""
    priv = ed25519.Ed25519PrivateKey.from_private_bytes(key)
    return priv.sign(data + _today_bytes())
